<section><h2>Zusatzaufgaben</h2><div class="worklist"><?php foreach($tasks as $tx):?><?php $cfg=json_decode($tx['config_json']?:'{}',true)?:[];$fields=$cfg['fields']??[];?><div class="task-card card"><div class="task-head"><div><b><?=App\Core\View::e($tx['title'])?></b><span><?=App\Core\View::e($tx['description'])?></span></div><small>Fällig <?=date('d.m.Y H:i',strtotime($tx['due_at']))?> · Nachfrist bis <?=date('H:i',strtotime($tx['grace_ends_at']))?> · <?=App\Core\View::e($tx['review_status'])?></small></div><?php if(!$tx['submitted_at'] && time()<=strtotime($tx['grace_ends_at'])):?><form method="post" action="/konto/auftraege/<?=$order['id']?>/aufgaben/<?=$tx['id']?>" class="form-grid"><?=App\Core\Csrf::field()?><?php foreach($fields as $field):?><?php $key=(string)($field['key']??'feld');$type=(string)($field['type']??'text');$label=(string)($field['label']??$key);$required=!empty($field['required']);?><label class="<?=$type==='multiselect'?'full':''?>"><?=App\Core\View::e($label)?><?php if($type==='number'):?><input type="number" name="field[<?=App\Core\View::e($key)?>]" <?=$required?'required':''?>><?php elseif($type==='scale'):?><input type="range" name="field[<?=App\Core\View::e($key)?>]" min="<?= (int)($field['min']??1) ?>" max="<?= (int)($field['max']??10) ?>" value="<?= (int)($field['min']??1) ?>"><?php elseif($type==='boolean'):?><select name="field[<?=App\Core\View::e($key)?>]" <?=$required?'required':''?>><option value="">Bitte wählen</option><option value="1">Ja</option><option value="0">Nein</option></select><?php elseif($type==='select'):?><select name="field[<?=App\Core\View::e($key)?>]" <?=$required?'required':''?>><option value="">Bitte wählen</option><?php foreach(($field['options']??[]) as $opt):?><option value="<?=App\Core\View::e($opt)?>"><?=App\Core\View::e($opt)?></option><?php endforeach;?></select><?php elseif($type==='multiselect'||$type==='checkboxes'):?><div class="checkbox-grid"><?php foreach(($field['options']??[]) as $opt):?><label class="check"><input type="checkbox" name="field[<?=App\Core\View::e($key)?>][]" value="<?=App\Core\View::e($opt)?>"><span><?=App\Core\View::e($opt)?></span></label><?php endforeach;?></div><?php else:?><input type="text" name="field[<?=App\Core\View::e($key)?>]" <?=$required?'required':''?>><?php endif;?></label><?php endforeach;?><button class="btn primary full">Aufgabe einreichen</button></form><?php endif;?></div><?php endforeach;?><?php if(!$tasks):?><div class="empty">Keine Zusatzaufgaben.</div><?php endif;?></div></section>
<section><h2>Beschädigung / Unbrauchbarkeit</h2><?php if($order['started_at']&&!$order['is_digital']):?><div class="card admin-form"><form method="post" action="/konto/auftraege/<?=$order['id']?>/beschaedigung" enctype="multipart/form-data" class="form-grid"><?=App\Core\Csrf::field()?><label class="full">Grund<textarea name="reason" rows="3" required></textarea></label><label class="full">Pflichtfoto<input type="file" name="evidence" accept="image/jpeg,image/png,image/webp" capture="environment" required></label><button class="btn full">Beschädigung melden</button></form></div><?php endif;?><div class="worklist"><?php foreach($damageCases as $dc):?><div class="work-row"><div><b>Beschädigung #<?=$dc['id']?></b><span><?=App\Core\View::e($dc['reason'])?> · <?=App\Core\View::e($dc['status'])?> · <?=date('d.m.Y H:i',strtotime($dc['created_at']))?></span></div></div><?php endforeach;?></div><?php foreach($damageRequests as $dr):?><?php if($dr['status']==='requested'):?><div class="card admin-form"><h3>Nachforderung #<?=$dr['id']?></h3><p><?=App\Core\View::e($dr['instructions'])?></p><p class="muted">Frist <?=date('d.m.Y H:i',strtotime($dr['deadline']))?> · Nachfrist <?=date('d.m.Y H:i',strtotime($dr['grace_ends_at']))?></p><form method="post" action="/konto/auftraege/<?=$order['id']?>/beschaedigung/nachforderung/<?=$dr['id']?>" enctype="multipart/form-data" class="form-grid"><?=App\Core\Csrf::field()?><?php if(in_array($dr['field_type'],['photo','video'],true)):?><label class="full">Datei<input type="file" name="evidence" accept="<?=$dr['field_type']==='video'?'video/mp4,video/webm':'image/jpeg,image/png,image/webp'?>" <?=$dr['field_type']==='photo'?'capture="environment"':''?> required></label><?php else:?><label class="full">Antwort<textarea name="response" rows="3" required></textarea></label><?php endif;?><button class="btn primary full">Nachforderung einreichen</button></form></div><?php endif;?><?php endforeach;?></section>
